body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background-color: var(--bg-color);
    color: var(--text-color);
    line-height: 1.6;
    padding: 2rem 1rem;
    display: flex;
    flex-direction: column;
    align-items: center;
    min-height: 100vh;
}

header {
    text-align: center;
    margin-bottom: 3rem;
    max-width: 600px;
}

header h1 {
    font-size: 2.5rem;
    font-weight: 800;
    color: #111827;
    margin-bottom: 0.5rem;
}

header p {
    color: #6b7280;
    font-size: 1.125rem;
}

main {
    width: 100%;
    max-width: 600px;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

.faq-container {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.example {
    background-color: var(--card-bg);
    border: 1px solid var(--border-color);
    border-radius: 0.75rem;
    overflow: hidden;
    transition: box-shadow 0.2s ease;
}

.example:hover {
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

.example h3 {
    font-size: 1rem;
    margin: 0;
}

.example button {
    width: 100%;
    text-align: left;
    padding: 1.25rem;
    background: none;
    border: none;
    font-family: inherit;
    font-size: 1.125rem;
    font-weight: 600;
    color: var(--text-color);
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 1rem;
}

.example button:focus-visible {
    outline: 2px solid var(--focus-ring);
    outline-offset: -2px;
}

.example button .icon {
    flex-shrink: 0;
    width: 1.25rem;
    height: 1.25rem;
    position: relative;
    transition: transform 0.2s ease;
}

.example button .icon::before,
.example button .icon::after {
    content: "";
    position: absolute;
    background-color: #9ca3af;
    transition: background-color 0.2s ease;
}

/* Plus icon */
.example button .icon::before {
    width: 2px;
    height: 100%;
    left: 50%;
    transform: translateX(-50%);
}

.example button .icon::after {
    width: 100%;
    height: 2px;
    top: 50%;
    transform: translateY(-50%);
}

.example button[aria-expanded="true"] .icon {
    transform: rotate(45deg);
}

.example button[aria-expanded="true"] .icon::before,
.example button[aria-expanded="true"] .icon::after {
    background-color: var(--primary-color);
}

.details {
    padding: 0 1.25rem 1.25rem;
    color: #4b5563;
    animation: slideDown 0.2s ease-out;
}

.details[hidden] {
    display: none;
}

@keyframes slideDown {
    from {
        opacity: 0;
        transform: translateY(-10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

footer {
    margin-top: auto;
    padding: 3rem 0;
    color: #9ca3af;
    font-size: 0.875rem;
    text-align: center;
}

@media (forced-colors: active) {
    .example button:focus-visible {
        outline: 2px solid ButtonText;
    }
    .example {
        border: 1px solid ButtonBorder;
    }
}
