+    faqButtons.forEach(button => {
+        button.addEventListener('click', () => {
+            const isExpanded = button.getAttribute('aria-expanded') === 'true';
+            const controlledId = button.getAttribute('aria-controls');
+            const content = document.getElementById(controlledId);
+
+            // Toggle state
+            button.setAttribute('aria-expanded', !isExpanded);
+            
+            if (isExpanded) {
+                content.setAttribute('hidden', '');
+            } else {
+                content.removeAttribute('hidden');
+            }
+        });
+
+        // Keyboard support: Space and Enter are handled by default for <button>
+        // But we can add Escape to close the currently focused expanded item
+        button.addEventListener('keydown', (event) => {
+            if (event.key === 'Escape') {
+                const isExpanded = button.getAttribute('aria-expanded') === 'true';
+                if (isExpanded) {
+                    button.setAttribute('aria-expanded', 'false');
+                    const controlledId = button.getAttribute('aria-controls');
+                    document.getElementById(controlledId).setAttribute('hidden', '');
+                }
+            }
+        });
+    });
+});
